import vine from '@vinejs/vine'

export const placeSearchValidator = vine.create({
  q: vine.string().trim().maxLength(120).optional(),
  /** Groups one search's requests for provider billing; generated by the app per search. */
  session: vine.string().trim().maxLength(64).optional(),
})

export const placeDetailsValidator = vine.create({
  id: vine.string().trim().minLength(3).maxLength(300),
  session: vine.string().trim().maxLength(64).optional(),
})
